import Foundation
import simd

/// Initial "tangled" poses generated by code.
/// Each puzzle level can use a different curve (or a pose saved by the design team).
enum TangleShape {
    /// Open trefoil knot: 3 crossings, it comes undone by pulling the tail out of the loops.
    case trefoil
    /// Open figure-eight knot: 4 crossings, harder.
    case figureEight

    /// Parametric curve: (x, z) is the projection seen from above, y is the height that decides who passes over.
    private func point(at angle: Float) -> SIMD3<Float> {
        switch self {
        case .trefoil:
            return SIMD3(sin(angle) + 2 * sin(2 * angle),
                         -sin(3 * angle),
                         cos(angle) - 2 * cos(2 * angle))
        case .figureEight:
            return SIMD3((2 + cos(2 * angle)) * cos(3 * angle),
                         sin(4 * angle),
                         (2 + cos(2 * angle)) * sin(3 * angle))
        }
    }

    /// Samples the curve (open, leaving a gap between head and tail) into `config.nodeCount` nodes
    /// `config.segmentLength` apart, scaled so that the length matches.
    func positions(config: TangleConfig) -> [SIMD3<Float>] {
        let gap: Float = 0.35
        let heightFactor: Float = 1
        let start: Float = 0.2
        let end = start + 2 * .pi - gap

        // Dense sampling and cumulative arc length.
        let samples = 2000
        var dense: [SIMD3<Float>] = []
        var arc: [Float] = [0]
        for k in 0...samples {
            var sample = point(at: start + (end - start) * Float(k) / Float(samples))
            // Exaggerates the height: clear over/under separation at the crossings.
            sample.y *= heightFactor
            if let last = dense.last { arc.append(arc.last! + simd_length(sample - last)) }
            dense.append(sample)
        }

        let targetLength = config.segmentLength * Float(config.nodeCount - 1)
        let scale = targetLength / arc.last!

        // Resampling at a constant step.
        var result: [SIMD3<Float>] = []
        var k = 0
        for node in 0..<config.nodeCount {
            let distance = arc.last! * Float(node) / Float(config.nodeCount - 1)
            while k < arc.count - 2 && arc[k + 1] < distance { k += 1 }
            let fraction = (distance - arc[k]) / max(arc[k + 1] - arc[k], 1e-6)
            let point = simd_mix(dense[k], dense[k + 1], SIMD3(repeating: fraction)) * scale
            result.append(point + SIMD3(0, config.radius, 0))
        }
        return result
    }
}
